const VITAL_SYS = 'patient-vitals-field';
// The vitals the charts draw (patient-vitals-field tags) and the units they must be recorded in.
const UNITS_OK = { 'vital-weight': ['kg'], 'vital-height': ['cm'] };

const visitIdx = helpers.index(resources.visits || []);
const patient = (visitIdx.byType.Patient || [])[0];

function vitalTag(o) {
  const tags = (o.meta && o.meta.tag) || [];
  const t = tags.find((x) => x && x.system && x.system.indexOf(VITAL_SYS) >= 0 && UNITS_OK[x.code]);
  return t ? t.code : undefined;
}

// ---- Growth charts (pediatric) ----------------------------------------------------------------
// Reference tables: growthTables() at the end of this code, generated from the WHO / CDC LMS files.
const GT = growthTables();
const DAYS_PER_MONTH = 30.4375; // WHO and CDC both turn age in days into months with 365.25 / 12

/*GROWTH-MATH-BEGIN*/
// LMS parameters at x, linearly interpolated between the bracketing table rows; undefined outside the table.
function lmsAt(table, x) {
  const last = table[table.length - 1];
  if (!(x >= table[0][0] && x <= last[0])) return undefined;
  let i = 1;
  while (i < table.length - 1 && table[i][0] < x) i++;
  const a = table[i - 1], b = table[i];
  const t = (x - a[0]) / (b[0] - a[0]);
  return { L: a[1] + t * (b[1] - a[1]), M: a[2] + t * (b[2] - a[2]), S: a[3] + t * (b[3] - a[3]) };
}
// The measurement at z-score z (the percentile curves): M (1 + L S z)^(1/L), or M e^(S z) when L = 0.
function valueAtZ(p, z) {
  return p.L === 0 ? p.M * Math.exp(p.S * z) : p.M * Math.pow(1 + p.L * p.S * z, 1 / p.L);
}
// z-score of y. restricted = WHO's rule for weight-based indicators: beyond ±3 SD, distance is measured in
// units of the 2-to-3 SD gap instead of the LMS curve, so extreme values are not exaggerated.
function zOf(p, y, restricted) {
  const z = p.L === 0 ? Math.log(y / p.M) / p.S : (Math.pow(y / p.M, p.L) - 1) / (p.L * p.S);
  if (!restricted || Math.abs(z) <= 3) return z;
  const sd3 = valueAtZ(p, z > 0 ? 3 : -3), sd2 = valueAtZ(p, z > 0 ? 2 : -2);
  return z > 0 ? 3 + (y - sd3) / (sd3 - sd2) : -3 + (y - sd3) / (sd2 - sd3);
}
// CDC's modified z-score (used only for its biologically-implausible-value flags).
function modifiedZ(p, y) {
  return y < p.M ? (y - p.M) / ((p.M - valueAtZ(p, -2)) / 2) : (y - p.M) / ((valueAtZ(p, 2) - p.M) / 2);
}
// Standard normal CDF (erf series, accurate to ~1e-10 for |z| ≤ 5), and its inverse by bisection.
function normCdf(z) {
  if (z <= -5) return 0;
  if (z >= 5) return 1;
  const x = z / Math.SQRT2;
  let term = x, sum = x;
  for (let n = 1; n < 200 && Math.abs(term) > 1e-17; n++) {
    term *= (-x * x) / n;
    sum += term / (2 * n + 1);
  }
  return 0.5 + sum / Math.sqrt(Math.PI);
}
function zForPercentile(pct) {
  let lo = -5, hi = 5;
  for (let i = 0; i < 80; i++) {
    const mid = (lo + hi) / 2;
    if (normCdf(mid) < pct / 100) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}
/*GROWTH-MATH-END*/

function fmtAge(months) {
  if (months < 1) return Math.round(months * DAYS_PER_MONTH) + ' d';
  if (months < 24) return Math.floor(months) + ' mo';
  const y = Math.floor(months / 12), m = Math.floor(months - y * 12);
  return y + ' y' + (m ? ' ' + m + ' mo' : '');
}
function ordinal(n) { const s = ['th', 'st', 'nd', 'rd'], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); }
function fmtPercentile(z) {
  const p = normCdf(z) * 100;
  if (p < 1) return '<1st';
  if (p > 99) return '>99th';
  return ordinal(Math.round(p));
}
const fmtDate = (iso) => (iso ? new Date(iso).toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }) : '');
// This visit (the page passes its encounter and date): its points are marked, and the chart set follows its age.
const thisVisitEnc = params.inputs.encounterId ? 'Encounter/' + params.inputs.encounterId : undefined;
const visitDate = params.inputs.visitDate;
// Age in months from the birth date to the measurement's calendar day in the viewer's time zone.
const fullBirthDate = patient && /^\d{4}-\d{2}-\d{2}$/.test(patient.birthDate || '') ? patient.birthDate : undefined;
function ageMonthsAt(iso) {
  const b = fullBirthDate.split('-').map(Number);
  const d = helpers.localDay(iso).split('-').map(Number);
  return (Date.UTC(d[0], d[1] - 1, d[2]) - Date.UTC(b[0], b[1] - 1, b[2])) / 864e5 / DAYS_PER_MONTH;
}
const growthSex = patient && (patient.gender === 'male' || patient.gender === 'female') ? patient.gender : undefined;
const ageNowMonths = fullBirthDate ? ageMonthsAt(visitDate || new Date().toISOString()) : undefined;

const CHART_SETS = {
  who: {
    label: 'Birth to 24 months (WHO)', standard: 'WHO Child Growth Standards', ageMin: 0, ageMax: 24,
    pcts: [2, 5, 10, 25, 50, 75, 90, 95, 98],
    charts: [
      { id: 'wfa', title: 'Weight-for-age', table: 'WHO wfa', kind: 'weight', x: 'age', yLabel: 'Weight (kg)', unit: 'kg', digits: 2, restricted: true, flag: [-6, 5] },
      { id: 'lfa', title: 'Length-for-age', table: 'WHO lfa', kind: 'height', x: 'age', yLabel: 'Length (cm)', unit: 'cm', digits: 1, flag: [-6, 6] },
      { id: 'wfl', title: 'Weight-for-length', table: 'WHO wfl', kind: 'weight', x: 'length', yLabel: 'Weight (kg)', unit: 'kg', digits: 2, restricted: true, flag: [-5, 5] },
    ],
  },
  cdc: {
    label: '2 to 20 years (CDC)', standard: 'CDC 2000 growth charts', ageMin: 24, ageMax: 240,
    pcts: [3, 5, 10, 25, 50, 75, 90, 95, 97],
    charts: [
      { id: 'wfa', title: 'Weight-for-age', table: 'CDC wfa', kind: 'weight', x: 'age', yLabel: 'Weight (kg)', unit: 'kg', digits: 1, modFlag: [-5, 8] },
      { id: 'sfa', title: 'Stature-for-age', table: 'CDC sfa', kind: 'height', x: 'age', yLabel: 'Stature (cm)', unit: 'cm', digits: 1, modFlag: [-5, 4] },
      { id: 'bmi', title: 'BMI-for-age', table: 'CDC bmi', kind: 'bmi', x: 'age', yLabel: 'BMI (kg/m²)', unit: 'kg/m²', digits: 1, modFlag: [-4, 8] },
    ],
  },
};

// One weight and one height per visit (the last taken, like the grid); BMI only from a pair of the same visit.
function growthMeasurements() {
  const lastBy = {};
  (resources.vitals || []).forEach((o) => {
    const tag = vitalTag(o);
    if (!tag) return;
    const at = o.effectiveDateTime || (o.effectivePeriod && o.effectivePeriod.start);
    if (!at) return;
    const key = ((o.encounter && o.encounter.reference) || 'Observation/' + o.id) + '|' + tag;
    if (!lastBy[key] || lastBy[key].at < at) lastBy[key] = { o, at, tag };
  });
  const byVisit = {};
  const out = [];
  Object.keys(lastBy).forEach((key) => {
    const { o, at, tag } = lastBy[key];
    const q = o.valueQuantity || {};
    const unit = String(q.unit || q.code || '').trim();
    let issue;
    if (typeof q.value !== 'number' || !(q.value > 0)) issue = 'no usable value';
    else if (UNITS_OK[tag].indexOf(unit.toLowerCase()) < 0) issue = 'unit "' + (unit || 'none') + '" — not converted to ' + UNITS_OK[tag][0];
    const m = { kind: tag === 'vital-weight' ? 'weight' : 'height', at, value: q.value, issue, ageMo: ageMonthsAt(at), enc: o.encounter && o.encounter.reference };
    out.push(m);
    const visit = key.split('|')[0];
    (byVisit[visit] = byVisit[visit] || {})[m.kind] = m;
  });
  Object.keys(byVisit).forEach((visit) => {
    const { weight, height } = byVisit[visit];
    if (!weight || !height || weight.issue || height.issue) return;
    weight.length = height.value; // weight-for-length pairs the weight with the same visit's length
    weight.lengthFrom = height;
    out.push({ kind: 'bmi', at: weight.at, value: weight.value / Math.pow(height.value / 100, 2), ageMo: weight.ageMo, from: [weight, height], enc: weight.enc });
  });
  return out.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0));
}
const growth = fullBirthDate && growthSex ? growthMeasurements() : [];
growth.forEach((m) => {
  if (m.kind === 'bmi' || m.issue) return;
  const set = m.ageMo < 24 ? CHART_SETS.who : CHART_SETS.cdc;
  const chart = set.charts.find((c) => c.kind === m.kind && c.x === 'age');
  const p = m.ageMo >= 0 && m.ageMo <= 240 ? lmsAt(GT[chart.table + ' ' + growthSex], m.ageMo) : undefined;
  if (!p) return;
  const fz = chart.modFlag ? modifiedZ(p, m.value) : zOf(p, m.value, chart.restricted);
  const lim = chart.modFlag || chart.flag;
  m.implausible = fz < lim[0] || fz > lim[1];
});

// The rows of one chart: x, percentile, z-score, and whether the point is plotted or flagged.
function chartRows(set, chart) {
  const table = GT[chart.table + ' ' + growthSex];
  const rows = [];
  let otherAges = 0;
  growth.forEach((m) => {
    if (m.kind !== chart.kind) return;
    if (chart.x === 'length' && m.length == null && !m.issue) return; // weight without a same-visit length
    if (!(m.ageMo >= set.ageMin && (m.ageMo < set.ageMax || (set.ageMax === 240 && m.ageMo <= 240)))) { otherAges++; return; }
    const x = chart.x === 'age' ? m.ageMo : m.length;
    const r = { m, x, y: m.value, note: m.issue || '' };
    const p = r.note ? undefined : lmsAt(table, x);
    if (!r.note && !p) r.note = chart.x === 'length' ? 'length outside the 45–110 cm table' : 'outside the table';
    if (p) {
      r.z = zOf(p, r.y, chart.restricted);
      const fz = chart.modFlag ? modifiedZ(p, r.y) : r.z;
      const lim = chart.modFlag || chart.flag;
      if (fz < lim[0] || fz > lim[1]) { r.implausible = true; r.note = 'implausible (' + (chart.modFlag ? 'modified ' : '') + 'z ' + fz.toFixed(1) + ') — not plotted on the line'; }
    }
    const sources = chart.kind === 'bmi' ? m.from : chart.x === 'length' && m.lengthFrom ? [m, m.lengthFrom] : [];
    const bad = sources.filter((s) => s.implausible).map((s) => s.kind);
    if (bad.length && !r.implausible && r.z != null) { r.implausible = true; r.note = 'from an implausible ' + bad.join(' and ') + ' — not plotted on the line'; }
    r.plotted = r.z != null && !r.implausible;
    rows.push(r);
  });
  return { rows, otherAges, table };
}

// ---- the chart (plain SVG so it reads like a clinical growth chart) ----
const CW = 660, CH = 420, PAD = { l: 52, r: 38, t: 14, b: 44 };
const PALETTE = {
  female: { curve: '#c2185b', mid: '#880e4f', tint: '#fdf6f9', point: '#0F347C' },
  male: { curve: '#1e6fd0', mid: '#0d3c8c', tint: '#f5f9fe', point: '#0F347C' },
};
const EHR_BLUE = '#2169F5';
function niceStep(span, target) {
  const raw = span / target, pow = Math.pow(10, Math.floor(Math.log10(raw)));
  const f = raw / pow;
  return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 5 ? 5 : 10) * pow;
}
function axisFor(set, chart, table) {
  if (chart.x === 'length') return { min: 45, max: 110, minor: 1, major: 5, label: 'Length (cm)', fmt: (v) => String(v) };
  if (set.ageMax === 24) return { min: 0, max: 24, minor: 1, major: 2, bold: 12, label: 'Age (months)', fmt: (v) => (v === 0 ? 'Birth' : String(v)) };
  return { min: 24, max: 240, minor: 6, major: 12, label: 'Age (years)', fmt: (v) => String(v / 12) };
}

function GrowthChart({ set, chart, rows, table, hover, setHover }) {
  const pal = PALETTE[growthSex];
  const xa = axisFor(set, chart, table);
  const tblRows = table.filter((r) => r[0] >= xa.min && r[0] <= xa.max);
  const curves = set.pcts.map((pct) => {
    const z = zForPercentile(pct);
    return { pct, pts: tblRows.map((r) => [r[0], valueAtZ({ L: r[1], M: r[2], S: r[3] }, z)]) };
  });
  const shown = rows.filter((r) => r.z != null && r.x >= xa.min && r.x <= xa.max);
  const rowIndex = (r) => rows.indexOf(r);
  const isThisVisit = (r) => thisVisitEnc && r.m.enc === thisVisitEnc;
  const ys = curves[0].pts.map((p) => p[1]).concat(curves[curves.length - 1].pts.map((p) => p[1]), shown.filter((r) => r.plotted).map((r) => r.y));
  const step = niceStep(Math.max.apply(null, ys) - Math.min.apply(null, ys), 9);
  const yMin = Math.floor(Math.min.apply(null, ys) / step) * step, yMax = Math.ceil(Math.max.apply(null, ys) / step) * step;
  const minorY = step / (Math.round(step / Math.pow(10, Math.floor(Math.log10(step) + 1e-9))) === 2 ? 4 : 5);
  const pw = CW - PAD.l - PAD.r, ph = CH - PAD.t - PAD.b;
  const sx = (x) => PAD.l + ((x - xa.min) / (xa.max - xa.min)) * pw;
  const sy = (y) => PAD.t + (1 - (y - yMin) / (yMax - yMin)) * ph;
  const inY = (y) => y >= yMin && y <= yMax;
  const grid = [];
  for (let x = xa.min; x <= xa.max + 1e-9; x += xa.minor) {
    const major = Math.abs((x - xa.min) % xa.major) < 1e-9 || Math.abs(((x - xa.min) % xa.major) - xa.major) < 1e-9;
    grid.push(<line key={'x' + x} x1={sx(x)} x2={sx(x)} y1={PAD.t} y2={PAD.t + ph} stroke={x === xa.bold ? '#b8c0cc' : major ? '#d9dee6' : '#eef1f5'} strokeWidth={x === xa.bold ? 1.2 : 1} />);
    if (major) grid.push(<text key={'xl' + x} x={sx(x)} y={PAD.t + ph + 15} fontSize="10.5" textAnchor="middle" fill="#475569">{xa.fmt(Math.round(x * 100) / 100)}</text>);
  }
  for (let i = 0; yMin + i * minorY <= yMax + 1e-9; i++) {
    const y = yMin + i * minorY;
    const major = Math.abs(y / step - Math.round(y / step)) < 1e-6;
    grid.push(<line key={'y' + i} x1={PAD.l} x2={PAD.l + pw} y1={sy(y)} y2={sy(y)} stroke={major ? '#d9dee6' : '#eef1f5'} />);
    if (major) grid.push(<text key={'yl' + i} x={PAD.l - 6} y={sy(y) + 3.5} fontSize="10.5" textAnchor="end" fill="#475569">{helpers.round(y, 2)}</text>);
  }
  // Curve labels at the right end, nudged apart so they never overlap.
  const labels = curves.map((c) => ({ pct: c.pct, y: sy(c.pts[c.pts.length - 1][1]) })).sort((a, b) => b.y - a.y);
  for (let i = 1; i < labels.length; i++) if (labels[i - 1].y - labels[i].y < 10) labels[i].y = labels[i - 1].y - 10;
  const line = shown.filter((r) => r.plotted).sort((a, b) => a.x - b.x);
  const path = (pts) => pts.map((p, i) => (i ? 'L' : 'M') + sx(p[0]).toFixed(1) + ' ' + sy(p[1]).toFixed(1)).join('');
  const tip = hover != null ? shown.find((r) => rowIndex(r) === hover) : null;
  const tipY = tip ? sy(Math.min(yMax, Math.max(yMin, tip.y))) : 0;
  return (
    <MUI.Box sx={{ position: 'relative', width: '100%', maxWidth: 760 }}>
      <svg viewBox={'0 0 ' + CW + ' ' + CH} width="100%" style={{ display: 'block', fontFamily: 'inherit' }} role="img" aria-label={chart.title + ' growth chart'}>
        <rect x={PAD.l} y={PAD.t} width={pw} height={ph} fill={pal.tint} />
        {grid}
        <rect x={PAD.l} y={PAD.t} width={pw} height={ph} fill="none" stroke="#9aa5b4" />
        <defs><clipPath id={'clip-' + set.ageMax + chart.id}><rect x={PAD.l} y={PAD.t} width={pw} height={ph} /></clipPath></defs>
        <g clipPath={'url(#clip-' + set.ageMax + chart.id + ')'}>
          {curves.map((c) => (
            <path key={c.pct} d={path(c.pts)} fill="none" stroke={c.pct === 50 ? pal.mid : pal.curve} strokeWidth={c.pct === 50 ? 2.2 : 1.1} strokeOpacity={c.pct === 50 ? 1 : 0.75} />
          ))}
          {line.length > 1 && <path d={path(line.map((r) => [r.x, r.y]))} fill="none" stroke={pal.point} strokeWidth="1.1" strokeOpacity="0.8" />}
        </g>
        {labels.map((l) => (
          <text key={l.pct} x={PAD.l + pw + 4} y={l.y + 3.5} fontSize="10" fontWeight={l.pct === 50 ? 700 : 400} fill={l.pct === 50 ? pal.mid : pal.curve}>{l.pct}</text>
        ))}
        {shown.map((r, i) => {
          const cx = sx(r.x), cy = sy(Math.min(yMax, Math.max(yMin, r.y)));
          if (!inY(r.y)) { // off the chart: a red arrow at the edge, pointing the way
            const up = r.y > yMax;
            return (
              <g key={i} onMouseEnter={() => setHover(rowIndex(r))} onMouseLeave={() => setHover(null)} style={{ cursor: 'pointer' }}>
                <path d={up ? 'M' + cx + ' ' + (cy + 1) + 'l-5 9h10z' : 'M' + cx + ' ' + (cy - 1) + 'l-5 -9h10z'} fill="#d32f2f" />
                <circle cx={cx} cy={cy + (up ? 5 : -5)} r="9" fill="transparent" />
              </g>
            );
          }
          return (
            <g key={i} onMouseEnter={() => setHover(rowIndex(r))} onMouseLeave={() => setHover(null)} style={{ cursor: 'pointer' }}>
              {r.plotted
                ? <circle cx={cx} cy={cy} r={isThisVisit(r) ? 5.5 : hover === rowIndex(r) ? 5 : 3.6} fill={isThisVisit(r) ? '#fff' : pal.point} stroke={isThisVisit(r) ? EHR_BLUE : '#fff'} strokeWidth={isThisVisit(r) ? 2.2 : 1.2} />
                : <path d={'M' + (cx - 4) + ' ' + (cy - 4) + 'l8 8m0 -8l-8 8'} stroke="#d32f2f" strokeWidth="2" />}
              <circle cx={cx} cy={cy} r="9" fill="transparent" />
            </g>
          );
        })}
        <text x={PAD.l + pw / 2} y={CH - 8} fontSize="11.5" textAnchor="middle" fill="#334155">{xa.label}</text>
        <text transform={'translate(13 ' + (PAD.t + ph / 2) + ') rotate(-90)'} fontSize="11.5" textAnchor="middle" fill="#334155">{chart.yLabel}</text>
      </svg>
      {tip && (
        <MUI.Paper elevation={3} sx={{ position: 'absolute', pointerEvents: 'none', px: 1.25, py: 0.75, fontSize: 12, lineHeight: 1.5, whiteSpace: 'nowrap', zIndex: 2,
          left: (sx(tip.x) / CW) * 100 + '%', top: (tipY / CH) * 100 + '%', transform: 'translate(' + (sx(tip.x) > CW * 0.7 ? 'calc(-100% - 12px)' : '12px') + ', -50%)' }}>
          <b>{fmtDate(tip.m.at)}</b> · {fmtAge(tip.m.ageMo)} · {helpers.round(tip.y, chart.digits)} {chart.unit}{chart.x === 'length' ? ' at ' + helpers.round(tip.x, 1) + ' cm' : ''}<br />
          {tip.plotted ? fmtPercentile(tip.z) + ' percentile' : '⚠ ' + tip.note}
        </MUI.Paper>
      )}
    </MUI.Box>
  );
}

const cellSx = { px: 1, py: 0.5, borderBottom: '1px solid #e5e7eb', textAlign: 'left', whiteSpace: 'nowrap' };
function GrowthTable({ chart, rows, otherAges, set, hover, setHover }) {
  const [all, setAll] = React.useState(false);
  const newest = rows.slice().reverse();
  const list = all ? newest : newest.slice(0, 10);
  return (
    <MUI.Box>
      {otherAges > 0 && (
        <MUI.Typography variant="caption" color="text.secondary" sx={{ display: 'block', pb: 0.5 }}>
          {otherAges + ' measurement' + (otherAges === 1 ? ' is' : 's are') + ' outside ' + set.label.split(' (')[0].toLowerCase() + ' — see the other chart set.'}
        </MUI.Typography>
      )}
      <MUI.Box sx={{ border: '1px solid #e5e7eb', borderRadius: 1, overflow: 'auto' }}>
      <MUI.Box component="table" sx={{ borderCollapse: 'collapse', width: '100%', fontSize: 12.5, '& td:last-of-type, & th:last-of-type': { pr: 2 } }}>
        <thead>
          <tr>{['Date', 'Age', chart.x === 'length' ? 'Weight @ length' : 'Value', 'Percentile', 'z'].map((h) => (
            <MUI.Box component="th" key={h} sx={{ ...cellSx, position: 'sticky', top: 0, background: '#f8fafc', fontWeight: 600 }}>{h}</MUI.Box>
          ))}</tr>
        </thead>
        <tbody>
          {list.map((r, i) => (
            <tr key={i} onMouseEnter={() => setHover(rows.indexOf(r))} onMouseLeave={() => setHover(null)} style={{ background: hover === rows.indexOf(r) ? '#E2F0FF' : undefined }}>
              <MUI.Box component="td" sx={cellSx}>{fmtDate(r.m.at)}</MUI.Box>
              <MUI.Box component="td" sx={cellSx}>{fmtAge(r.m.ageMo)}</MUI.Box>
              <MUI.Box component="td" sx={cellSx}>{helpers.round(r.y, chart.digits) + ' ' + chart.unit + (chart.x === 'length' && r.x != null ? ' @ ' + helpers.round(r.x, 1) + ' cm' : '')}</MUI.Box>
              {r.plotted
                ? [<MUI.Box component="td" key="p" sx={cellSx}>{fmtPercentile(r.z)}</MUI.Box>, <MUI.Box component="td" key="z" sx={cellSx}>{r.z.toFixed(2)}</MUI.Box>]
                : <MUI.Box component="td" colSpan={2} sx={{ ...cellSx, color: r.implausible || r.m.issue ? '#b91c1c' : 'text.secondary', whiteSpace: 'normal' }}>{(r.implausible || r.m.issue ? '⚠ ' : '') + r.note}</MUI.Box>}
            </tr>
          ))}
          {list.length === 0 && <tr><MUI.Box component="td" colSpan={5} sx={{ ...cellSx, color: 'text.secondary' }}>No measurements in this age range.</MUI.Box></tr>}
        </tbody>
      </MUI.Box>
      </MUI.Box>
      {newest.length > 10 && !all && (
        <MUI.Button size="small" onClick={() => setAll(true)} sx={{ textTransform: 'none', mt: 0.5 }}>{'Show all (' + newest.length + ')'}</MUI.Button>
      )}
    </MUI.Box>
  );
}

function GrowthCard({ set, chart }) {
  const [hover, setHover] = React.useState(null);
  const { rows, otherAges, table } = chartRows(set, chart);
  return (
    <MUI.Paper variant="outlined" sx={{ p: 1.5 }}>
