function GrowthSection() {
  const defaultSet = ageNowMonths != null && ageNowMonths < 24 ? 'who' : 'cdc';
  const [setId, setSetId] = React.useState(defaultSet);
  if (!fullBirthDate) return <Report.Note tone="info">No growth charts: the patient has no full date of birth.</Report.Note>;
  if (!growthSex) return <Report.Note tone="info">{'No growth charts: WHO and CDC charts are sex-specific and the patient’s sex is ' + ((patient && patient.gender) || 'not recorded') + '.'}</Report.Note>;
  const set = CHART_SETS[setId];
  const sexWord = growthSex === 'female' ? 'Girls' : 'Boys';
  const pcts = set.pcts;
  return (
    <Report.Section title="Growth charts">
      <MUI.Tabs value={setId} onChange={(e, v) => setSetId(v)} sx={{ minHeight: 36, mb: 1 }}>
        {Object.keys(CHART_SETS).map((id) => <MUI.Tab key={id} value={id} label={CHART_SETS[id].label} sx={{ textTransform: 'none', minHeight: 36, py: 0 }} />)}
      </MUI.Tabs>
      <MUI.Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        {sexWord + ' · ' + (setId === 'who' ? 'WHO, birth–24 months' : 'CDC, 2–20 years') + ' · percentiles ' + ordinal(pcts[0]) + '–' + ordinal(pcts[pcts.length - 1]) + (visitDate ? ' · age at this visit: ' + fmtAge(ageNowMonths) : '')}
      </MUI.Typography>
      <MUI.Stack spacing={2.5}>
        {set.charts.map((chart) => <GrowthCard key={setId + chart.id} set={set} chart={chart} />)}
      </MUI.Stack>
    </Report.Section>
  );
}

